-- 읽기 전용 검증 (적용 후) — 모두 true여야 한다.
select
  (select pg_get_constraintdef(oid) like '%nicepay%' and pg_get_constraintdef(oid) like '%toss%' and pg_get_constraintdef(oid) like '%portone%' and pg_get_constraintdef(oid) like '%mock%' from pg_constraint where conname = 'orders_payment_provider_check')   as orders_provider_check_must_be_true,
  (select pg_get_constraintdef(oid) like '%nicepay%' and pg_get_constraintdef(oid) like '%toss%' and pg_get_constraintdef(oid) like '%portone%' and pg_get_constraintdef(oid) like '%mock%' from pg_constraint where conname = 'payments_payment_provider_check') as payments_provider_check_must_be_true,
  (select pg_get_constraintdef(oid) like '%approving%' and pg_get_constraintdef(oid) like '%pending%' and pg_get_constraintdef(oid) like '%paid%' and pg_get_constraintdef(oid) like '%cancelled%' and pg_get_constraintdef(oid) like '%done%' from pg_constraint where conname = 'orders_status_check') as status_check_must_be_true,
  (select count(*) = 5 from information_schema.columns where table_name = 'orders' and column_name in ('pg_claim_id','pg_claimed_at','pg_tid','pg_review_reason','pg_review_at')) as columns_must_be_true,
  (select count(*) = 1 from pg_trigger where tgname = 'orders_guard_pg_state' and not tgisinternal)                                                                                     as guard_trigger_must_be_true,
  (select count(*) = 1 from pg_trigger where tgname = 'orders_guard_status_transition' and not tgisinternal)                                                                            as status_trigger_still_one_must_be_true,
  (select pg_get_functiondef('public.orders_guard_status_transition()'::regprocedure) like '%app.nicepay_write%' and pg_get_functiondef('public.orders_guard_status_transition()'::regprocedure) like '%old.status = ''paid'' and new.status in (''done'', ''cancelled'')%') as status_trigger_extended_and_legacy_kept_must_be_true,
  (select count(*) = 10 from pg_proc where proname in ('nicepay_record_verified_approval','nicepay_record_pg_cancel','confirm_nicepay_payment','nicepay_confirm_reviewed','nicepay_order_context','nicepay_claim_order','nicepay_release_order','nicepay_mark_review','nicepay_expire_stale_claims','nicepay_resolve_review') and prosecdef) as rpcs_secdef_must_be_true,
  (select bool_and(not has_function_privilege('authenticated', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and has_function_privilege('service_role', p.oid, 'execute'))
     from pg_proc p where p.proname in ('nicepay_record_verified_approval','nicepay_record_pg_cancel','confirm_nicepay_payment','nicepay_confirm_reviewed','nicepay_order_context','nicepay_claim_order','nicepay_release_order','nicepay_mark_review','nicepay_expire_stale_claims','nicepay_resolve_review')) as rpcs_service_role_only_must_be_true,
  (select relrowsecurity from pg_class where oid = 'public.nicepay_review_actions'::regclass) as audit_rls_must_be_true,
  (select count(*) = 1 from pg_trigger where tgrelid = 'public.nicepay_review_actions'::regclass and tgname = 'nicepay_review_actions_append_only' and not tgisinternal) as audit_append_only_must_be_true,
  (select not has_table_privilege('authenticated', 'public.nicepay_review_actions', 'select') and not has_table_privilege('anon', 'public.nicepay_review_actions', 'select') from (select 1) x) as audit_no_client_access_must_be_true,
  (select pg_get_functiondef('public._issue_membership_and_record_payment(orders,text,text)'::regprocedure) like '%case when p_order.payment_provider = ''nicepay'' then ''nicepay'' else null end%') as helper_records_nicepay_provider_must_be_true,
  (select pg_get_functiondef('public.fulfill_order(uuid)'::regprocedure) like '%-- fulfill_nicepay_guard begin%' and pg_get_functiondef('public.fulfill_order(uuid)'::regprocedure) like '%NICEPAY 결제 주문은 PG 승인으로만 발급할 수 있어요%') as fulfill_order_rejects_nicepay_must_be_true,
  (select pg_get_functiondef('public._refund_membership_core(uuid,uuid,boolean,boolean)'::regprocedure) like '%-- nicepay_pg_cancel_guard begin (v2)%') as refund_core_requires_pg_cancel_must_be_true,
  (select relrowsecurity from pg_class where oid = 'public.nicepay_pg_cancels'::regclass) as pg_cancels_rls_must_be_true,
  (select relrowsecurity from pg_class where oid = 'public.nicepay_pg_approvals'::regclass) as pg_approvals_rls_must_be_true,
  (select count(*) = 1 from pg_trigger where tgrelid = 'public.nicepay_pg_approvals'::regclass and tgname = 'nicepay_pg_approvals_append_only' and not tgisinternal) as pg_approvals_append_only_must_be_true,
  (select not has_table_privilege('authenticated', 'public.nicepay_pg_approvals', 'select') and not has_table_privilege('anon', 'public.nicepay_pg_approvals', 'select') from (select 1) x) as pg_approvals_no_client_access_must_be_true,
  (select not has_table_privilege('authenticated', 'public.nicepay_pg_cancels', 'select') and not has_table_privilege('anon', 'public.nicepay_pg_cancels', 'select') from (select 1) x) as pg_cancels_no_client_access_must_be_true,
  (select strpos(lower(d), 'for update') > 0 and strpos(lower(d), 'for update') < strpos(d, 'nicepay_pg_approvals') from (select pg_get_functiondef('public.nicepay_release_order(uuid,uuid,text)'::regprocedure) d) x) as release_locks_order_before_reading_approvals_must_be_true,
  (select pg_get_functiondef('public.confirm_real_payment(uuid,text,integer)'::regprocedure) not like '%nicepay%') as confirm_real_payment_untouched_must_be_true,
  (select to_regprocedure('public.admin_center_settlement_summary(date,date)') is null or pg_get_functiondef('public.admin_center_settlement_summary(date,date)'::regprocedure) like '%''portone'', ''nicepay''%') as settlement_includes_nicepay_or_absent_must_be_true,
  (select pg_get_functiondef('public.nicepay_claim_order(uuid)'::regprocedure) like '%-- nicepay_claim_gate begin%' and pg_get_functiondef('public.nicepay_claim_order(uuid)'::regprocedure) like '%nicepay_checkout_mode()%') as claim_gate_must_be_true;
